                },
                "_exp_array_exists": {
                    "id": "https://dcc.icgc.org/donor-centric/_summary/_exp_array_exists",
                    "type": "boolean"
                },
                "_exp_seq_exists": {
                    "id": "https://dcc.icgc.org/donor-centric/_summary/_exp_seq_exists",
                    "type": "boolean"
                },
                "_jcn_exists": {
                    "id": "https://dcc.icgc.org/donor-centric/_summary/_jcn_exists",
