                },
                "_meth_array_exists": {
                    "id": "https://dcc.icgc.org/donor-centric/_summary/_meth_array_exists",
                    "type": "boolean"
                },
                "_meth_seq_exists": {
                    "id": "https://dcc.icgc.org/donor-centric/_summary/_meth_seq_exists",
