                    },
                    "required": [
                        "path"
                    ]
                }
            ]
        },
        "meterExec": {
            "title": "meter extracting data from the output of a shell command/executable",
            "allOf": [
                {
                    "$ref": "#/definitions/meter"
                },
                {
                    "properties": {
                        "protocol": {
                            "type": "string",
                            "enum": [
                                "exec"
                            ]
                        },
                        "command": {
                            "type": "string",
                            "description": "Command to be executed. Only possible if running as non root. Output will be parsed."
