                            "repository": {
                                "oneOf": [
                                    {
                                        "type": "object",
                                        "required": [
                                            "commit"
                                        ],
                                        "properties": {
                                            "commit": {
                                                "oneOf": [
                                                    {
                                                        "type": "object",
                                                        "required": [
                                                            "diff"
